INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die DSGVO nur für Unternehmen in der EU bindend?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt auch für Datenverarbeitung außerhalb der EU bei EU-Bürgern"}, {"text": "Ja", "correct": false, "because": "Nicht auf EU beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Recht der DSGVO ist für den Schutz der Betroffenen entscheidend?', 3, '[{"text": "Recht auf Löschung", "correct": true, "because": "Ermöglicht Entfernung persönlicher Daten"}, {"text": "Farbe der Datenschutzerklärung", "correct": false, "because": "Kein Einfluss"}, {"text": "Schriftart der Dokumente", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die DSGVO verlangt eine Einwilligung zur Datenverarbeitung. b) Sie gilt nur für digitale Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt auch für analoge Daten"}, {"text": "Beides stimmt", "correct": false, "because": "Nicht nur digital"}, {"text": "Nur b) stimmt", "correct": false, "because": "Einwilligung erforderlich"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme solltest du gemäß DSGVO priorisieren, um Daten zu schützen?', 4, '[{"text": "Datenschutz durch Technik", "correct": true, "because": "Fördert eingebauten Schutz"}, {"text": "Farbe der Webseite", "correct": false, "because": "Kein Schutzfaktor"}, {"text": "Design der Formulare", "correct": false, "because": "Ästhetisch, nicht sicherheitsrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Unternehmen die DSGVO ignorieren, wenn es keine personenbezogenen Daten verarbeitet?', 2, '[{"text": "Ja", "correct": true, "because": "Ohne personenbezogene Daten nicht anwendbar"}, {"text": "Nein", "correct": false, "because": "Nur bei Datenverarbeitung relevant"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die DSGVO nur für Unternehmen in der EU bindend?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für Datenverarbeitung von EU-Bürgern weltweit"}, {"text": "Ja", "correct": false, "because": "Nicht auf EU beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Recht der DSGVO ist für den Schutz der Betroffenen entscheidend?', 3, '[{"text": "Recht auf Löschung", "correct": true, "because": "Ermöglicht Entfernung persönlicher Daten"}, {"text": "Farbe der Datenschutzerklärung", "correct": false, "because": "Kein Einfluss"}, {"text": "Schriftart der Webseite", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die DSGVO verlangt eine Einwilligung zur Datenverarbeitung. b) Sie gilt nur für öffentliche Unternehmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Einwilligung nötig, gilt für alle"}, {"text": "Beides stimmt", "correct": false, "because": "Nicht nur öffentlich"}, {"text": "Nur b) stimmt", "correct": false, "because": "Einwilligung erforderlich"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme solltest du gemäß DSGVO priorisieren, um Daten zu schützen?', 4, '[{"text": "Datenschutz durch Technik", "correct": true, "because": "Technische Maßnahmen vorgeschrieben"}, {"text": "Farbe der Webseite", "correct": false, "because": "Kein Schutzfaktor"}, {"text": "Schriftgröße der Dokumente", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Unternehmen ohne Datenschutzbeauftragten DSGVO-konform sein?', 2, '[{"text": "Ja", "correct": true, "because": "Nur unter bestimmten Bedingungen nötig"}, {"text": "Nein", "correct": false, "because": "Nicht immer erforderlich"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die DSGVO in allen EU-Ländern direkt anwendbar?', 2, '[{"text": "Ja", "correct": true, "because": "Sie ist eine EU-Verordnung"}, {"text": "Nein", "correct": false, "because": "Keine nationale Umsetzung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Recht der Betroffenen ist nach der DSGVO zentral?', 3, '[{"text": "Recht auf Auskunft", "correct": true, "because": "Ermöglicht Einsicht in Daten"}, {"text": "Farbe der Datensätze", "correct": false, "because": "Kein Recht"}, {"text": "Schriftart der Berichte", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die DSGVO gilt nur für Unternehmen. b) Sie schützt personenbezogene Daten.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Gilt auch für Behörden"}, {"text": "Nur b) stimmt", "correct": true, "because": "Datenschutz ist Ziel"}, {"text": "Beides stimmt", "correct": false, "because": "Aussage a) falsch"}, {"text": "Beides falsch", "correct": false, "because": "Aussage b) korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Aspekt solltest du bei der Einhaltung der DSGVO priorisieren?', 4, '[{"text": "Einwilligung der Betroffenen", "correct": true, "because": "Grundlage der Verarbeitung"}, {"text": "Design der Webseite", "correct": false, "because": "Sekundär"}, {"text": "Farbe der Datenschutzerklärung", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die DSGVO ohne nationale Gesetze angewendet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Direkt anwendbar"}, {"text": "Nein", "correct": false, "because": "Nationale Ergänzungen optional"}]');
